head.script:
scwin.screenId = "jlddst36910";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_dtruleLawNo", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.dtruleLawNo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("dtruleLawNo"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.dtruleLawNo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("dtruleLawNo")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.initValue();
        $(document).find('h2[id=txt_law1Title]').append(dma_hiddenStore.get("law1TitleVal"));
        $(document).find('h2[id=txt_law2Title]').append(dma_hiddenStore.get("law2TitleVal"));
        $(document).find('div[id=dialog-loading]').css("display", "none");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst36910.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst36910.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_GetLawItemContents_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GetLawItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawItemContents_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_GetLawDtruleItemContents_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GetLawDtruleItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawDtruleItemContents_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = async function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.getLawItemContents();
    await scwin.getLawDtruleItemContents();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getLawItemContents
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getLawItemContents = async function () {
    /* sdd-asis-lifecycle:begin fn_GetLawItemContents — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_method').setValue("viewLawItem");
    const result = await scwin.tx_fn_GetLawItemContents_xhr();
    $("#law1").append(result);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getLawDtruleItemContents
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getLawDtruleItemContents = async function () {
    /* sdd-asis-lifecycle:begin fn_GetLawDtruleItemContents — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_method').setValue("viewLawDtruleItem");
    let result = await scwin.tx_fn_GetLawDtruleItemContents_xhr();
    result = scwin.trim(result);
    if (result !== '' || result != null) {
        $("#law2").append(result);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.trim = function (_str) {
    /* sdd-asis-lifecycle:begin fn_Trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    /* sdd-asis-lifecycle:end */
};
